"""Explain disabled KCSAN, signal-fence tags and atomic annotation branches."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1661': ('검사 창구를 쉬는 날에도 같은 양식으로 요청할 수 있게 빈 창구를 남긴다고 생각해 보세요. 요청이 받아들여지는 모양과 실제 검사가 진행되는지는 달라요.', 'KCSAN 비활성 구현의 반환값과 검사 부재를 이해합니다.', 'CONFIG_KCSAN 꺼짐 → begin은 받은 sa 반환 → end는 빈 함수라고 적으세요. 새 할당과 목록 등록은 없다고 표시하세요.', ['CONFIG_KCSAN은 커널에 KCSAN 검사 기능을 넣을지 정하는 설정이에요. 꺼진 구성에서도 기존 호출 코드를 번역할 수 있도록 같은 이름의 대체 정의를 제공해요. 이런 빈 대체 구현을 stub이라고 부르기도 해요.', '비활성 구성의 kcsan_scoped_access는 내용이 없는 구조체예요. 활성 구성의 주소·크기·종류·목록 필드를 그대로 유지하는 구조가 아니에요. 코드는 설정에 따라 다른 정의를 선택해요.', 'begin_scoped_access의 이쪽 본문은 return sa예요. 호출자가 넘긴 sa 주소를 그대로 돌려줘요. 예를 들어 카드 자리 주소 A를 넘기면 A를 받아요. 새 카드 B를 할당하거나 검사 목록에 추가하는 코드가 없어요.', 'end_scoped_access는 빈 inline 함수예요. cleanup 매크로도 이 구성에서는 __maybe_unused만 남아요. 이것은 사용하지 않는 변수에 대한 경고를 줄이는 표시이며 종료 검사 함수를 자동 호출하는 속성과는 달라요.', '빈 함수 호출이라도 인자에 들어 있는 부수 효과는 C의 평가 규칙을 따라요. 반면 검사 기능 자체는 제공하지 않아요. 함수 이름이 소스에 남아 있다는 사실을 실제 검사를 했다는 증거로 사용하면 안 돼요.', '검사를 꺼서 경고가 없다는 것은 경쟁 상태가 없다는 증명이 아니에요. 경쟁 상태는 여러 작업의 접근 순서에 따라 문제가 생기는 상황이에요. 또한 이 빈 구조체는 커널이 쓰는 GNU C 환경의 코드이므로 모든 C 컴파일 환경에 그대로 통한다고 가정하지 않아요.'], [('KCSAN 비활성 구성에서 begin_scoped_access는 무엇을 반환하나요?', ['새로 할당한 검사 객체의 주소예요', '호출자가 전달한 sa 주소예요'], '정답은 두 번째예요. 빈 대체 구현의 본문은 return sa예요. 새 메모리 할당이나 검사 목록 등록이 없으므로 새로운 검사 객체가 만들어졌다고 해석하면 안 돼요.'), ('KCSAN을 껐더니 경고가 없어요. 경쟁 상태가 없다는 증거인가요?', ['아니요. 이 구성에서는 검사 기능이 없는 것이에요', '네. 설정을 끄면 모든 경쟁 상태가 제거돼요'], '정답은 첫 번째예요. 점검하지 않은 것과 점검해서 문제가 없음을 확인한 것은 달라요. 설정을 꺼도 실제 데이터 접근과 동시 실행 오류가 자동으로 바뀌지는 않아요.')]), 'os1662': ('종류를 알리려고 빨간 번호표를 쓴다고 모든 빨간 물건이 같은 뜻은 아니에요. 여기의 상수도 검사 도구가 알아볼 표지로 쓰는 것이에요.', 'signal fence 계측과 메모리 순서 상수의 태그 용도를 이해합니다.', '컴파일러 장벽 → signal fence로 종류 알림 → 컴파일러 장벽을 그리세요. 실제 CPU 장벽 구현은 별도 칸에 적으세요.', ['weak memory 검사는 메모리 접근 순서와 관련된 동시 실행 문제를 다루는 검사예요. CONFIG_KCSAN_WEAK_MEMORY와 현재 파일의 __SANITIZE_THREAD__ 표시가 함께 있으면 이 계측 경로가 선택돼요. 계측은 검사에 필요한 정보를 코드에 붙이는 일이에요.', '공통 매크로는 barrier(), __atomic_signal_fence(...), barrier() 순서예요. 양쪽 barrier는 컴파일러가 접근을 함부로 재배치하지 못하도록 하는 컴파일러 장벽이에요. 이것을 디스크 저장이나 모든 CPU의 하드웨어 장벽과 같다고 읽으면 안 돼요.', '여기서는 스레드 검사 도구가 signal fence를 알아채는 경로를 다시 활용해 KCSAN에 장벽 종류를 알려요. signal fence를 호출했다는 사실만으로 모든 CPU가 특정 장벽 명령을 실행했다는 뜻은 아니에요.', '종류를 구별할 태그로 mb에는 SEQ_CST, wmb에는 ACQ_REL, rmb에는 ACQUIRE, release에는 RELEASE 상수를 써요. 태그는 수신 쪽에서 무엇을 알리는 요청인지 구별하는 번호표 같은 것이에요.', 'C11과 LKMM은 각각 C 언어와 Linux 커널의 메모리 동작 규칙을 다루는 모델이에요. 원문은 여기의 태그 대응이 임의로 정한 것이며 두 모델 사이의 실제 순서 대응을 나타내지 않는다고 명시해요. wmb가 ACQ_REL 태그를 쓴다고 두 의미가 같아지는 것은 아니에요.', '검사 알림과 실제 순서를 구현하는 CPU별 장벽을 나누어 추적하세요. 알림을 전달한 경로를 확인하면 계측 연결을 이해할 수 있지만, 그 기록만으로 모든 CPU 순서나 두 메모리 모델의 동등함을 증명할 수는 없어요.'], [('wmb에 ACQ_REL 상수를 쓰므로 C11과 LKMM의 의미가 정확히 같다고 할 수 있나요?', ['네. 두 메모리 모델이 동일하다는 증거예요', '아니요. 여기서는 검사 도구가 구별할 태그로 사용해요'], '정답은 두 번째예요. 원문은 이 대응이 임의이며 실제 모델 사이의 순서 대응이 아니라고 밝혀요. 번호표로 빌려 쓴 이름을 기술의 의미가 같다는 주장으로 바꾸면 안 돼요.'), ('signal fence 양쪽의 barrier()를 읽을 때 무엇을 구별해야 하나요?', ['컴파일러의 순서 제한과 실제 CPU 장벽을 구별해야 해요', '언제나 디스크 내용을 저장하는 flush와 같아요'], '정답은 첫 번째예요. 이 매크로는 컴파일러 장벽과 KCSAN에 전달할 표시를 구성해요. 실제 CPU 동작과 영구 저장은 별도의 구현과 규칙을 확인해야 해요.')]), 'os1663': ('갈림길 안내를 위에서부터 읽고 처음 맞는 길 하나를 고르는 모습을 생각해 보세요. 뒤의 길도 조건이 맞는다고 두 길을 동시에 가지는 않아요.', '전처리 분기의 우선순위와 직접 장벽 알림 경로를 이해합니다.', 'WEAK_MEMORY 켜짐에서 계측 있음 → signal fence, 계측 없음·명시적 표시 있음 → 직접 hook, 둘 다 없음 → 빈 코드를 적으세요.', ['이 헤더는 #if, #elif, #else로 KCSAN에 장벽을 알리는 방법을 골라요. 전처리는 컴파일 전에 코드 조각을 선택하는 단계예요. 실행할 때마다 세 경로를 모두 호출하는 반복문이 아니에요.', '첫 조건은 CONFIG_KCSAN_WEAK_MEMORY와 __SANITIZE_THREAD__가 함께 있는지예요. 두 조건을 만족하면 앞 수업의 signal-fence 경로를 써요. 먼저 맞는 분기가 선택되므로 아래 elif로 더 내려가지 않아요.', '첫 조건이 거짓이면 다음 조건을 봐요. WEAK_MEMORY가 켜지고 __KCSAN_INSTRUMENT_BARRIERS__라는 명시적 계측 표시가 있으면 직접 hook에 연결해요. hook은 여기서 검사 런타임의 알림 함수예요.', '이 직접 경로에서는 kcsan_mb → __kcsan_mb, kcsan_wmb → __kcsan_wmb, kcsan_rmb → __kcsan_rmb, kcsan_release → __kcsan_release로 이름이 이어져요. 별칭은 이름을 다른 코드 이름으로 연결하는 규칙이에요.', '계측 표시와 명시적 표시가 둘 다 있고 WEAK_MEMORY도 켜졌다면 첫 signal-fence 분기가 이겨요. WEAK_MEMORY가 꺼졌거나 두 계측 경로가 모두 해당하지 않으면 빈 do { } while (0)을 써요. 안에 실행할 알림이 없다는 뜻이에요.', '빈 KCSAN 알림이라고 실제 CPU 장벽까지 모두 없어졌다고 생각하면 안 돼요. 다른 헤더에서 알림과 실제 기반 장벽을 함께 호출할 수 있어요. 검사 도구에 알려 주는 길과 데이터 순서를 실제로 지키는 길을 구별하세요.'], [('WEAK_MEMORY와 명시적 장벽 계측 표시만 있고 __SANITIZE_THREAD__는 없는 파일은 어느 경로인가요?', ['언제나 첫 signal-fence 경로예요', '직접 __kcsan 장벽 hook에 연결하는 경로예요'], '정답은 두 번째예요. 첫 분기는 __SANITIZE_THREAD__를 요구하므로 이 경우에는 맞지 않아요. 다음 elif가 명시적 표시를 확인해 직접 함수를 연결해요.'), ('어느 계측 경로에도 해당하지 않을 때 kcsan_mb의 본문은 무엇인가요?', ['빈 do-while 블록이에요', '모든 CPU의 full 장벽 명령을 직접 실행해요'], '정답은 첫 번째예요. else는 do { } while (0)으로 알림을 비워 둬요. 이 검사 알림의 기본값을 실제 CPU별 장벽 구현과 혼동하면 안 돼요.')]), 'os1664': ('체크표의 원자적, 쓰기, 복합 세 칸을 켜면 각각 다른 성질을 함께 표시할 수 있어요. 체크표를 생략하는 설정이 실제 데이터 작업까지 지우는 것은 아니에요.', '원자적 접근 플래그와 인자를 버리는 매크로를 구별합니다.', 'ATOMIC=100, WRITE=001, COMPOUND=010을 적고 100 | 001 | 010 = 111 = 7을 계산하세요.', ['KCSAN에 접근 종류를 알리는 비트에는 ATOMIC=4, WRITE=1, COMPOUND=2가 있어요. ATOMIC은 원자적 접근 표시, WRITE는 쓰기 표시, COMPOUND는 읽기·쓰기 복합 표시예요. 표시 자체가 실제 연산을 원자적으로 만드는 것은 아니에요.', '원자적 읽기는 4예요. 쓰기 표시가 없으면 읽기라는 규칙을 사용해요. 원자적 쓰기는 4 | 1 = 5이고, 원자적 읽기·쓰기는 4 | 1 | 2 = 7이에요. |는 켜진 비트 칸을 합치는 OR 연산이에요.', 'CONFIG_KCSAN_IGNORE_ATOMICS가 켜지면 세 원자적 검사 매크로는 모두 do { } while (0)으로 바뀌어요. 괄호 안에 전달한 인자를 본문에서 전혀 사용하지 않아요. 따라서 직접 매크로에 쓴 인자 코드는 치환 결과에서 사라져요.', '예를 들어 주소를 반환하면서 호출 횟수를 늘리는 next_ptr()를 이 빈 매크로의 인자로 직접 넣었다고 해 보세요. 치환 뒤에는 next_ptr()가 남지 않으므로 그 호출도 일어나지 않아요. 빈 함수라면 호출 전에 인자를 평가한다는 앞 수업과 다른 경우예요.', '그러나 바깥 instrument_atomic_read 함수에 next_ptr()를 전달한 경우는 달라요. 바깥 함수의 인자 평가까지 이 안쪽 매크로가 지우는 것은 아니에요. 그 함수 안에는 kasan_check_read 호출도 따로 있어요. KASAN은 메모리 접근의 유효성 오류를 찾는 다른 검사 도구예요.', '그러므로 원자적 KCSAN 검사를 무시하는 설정을 모든 검사·인자·데이터 작업을 없애는 설정으로 읽으면 안 돼요. 어느 호출의 인자인지와 어느 매크로가 사라지는지 한 단계씩 확인하세요. 중요한 상태 변경을 검사 인자에 숨기지 않으면 이런 혼동을 줄일 수 있어요.'], [('원자적 읽기·쓰기 복합 접근의 플래그 값은 얼마인가요?', ['ASSERT 하나인 8이에요', 'ATOMIC·WRITE·COMPOUND를 합친 7이에요'], '정답은 두 번째예요. 이진수 100 | 001 | 010 = 111이고 십진수로 7이에요. ASSERT=8은 다른 의미의 비트여서 이 세 성질을 대신하지 않아요.'), ('IGNORE_ATOMICS가 켜졌을 때 빈 원자적 검사 매크로에 직접 쓴 side_effect() 인자는 호출되나요?', ['아니요. 이 매크로는 인자 코드를 치환 결과에 남기지 않아요', '네. 빈 inline 함수와 언제나 같아요'], '정답은 첫 번째예요. 본문이 인자를 사용하지 않는 매크로이므로 해당 호출 코드가 사라져요. 바깥 함수의 인자 평가나 빈 함수의 C 평가 규칙까지 같은 것으로 넓혀 생각하면 안 돼요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_411.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
